    }
    if (tap.intent === 'missed' && new Date(dose.scheduledAt).getTime() > new Date(sentAt).getTime()) {
      return { ...base, outcome: 'refused', dose, reply: L.no_dose, guardrail: 'G10', reason: 'a dose cannot be missed before its time' };
