  const cut = rest.lastIndexOf(':');
  if (cut <= 0) return null;
  const doseId = rest.slice(0, cut);
  const intent = rest.slice(cut + 1);
  if (!/^[A-Za-z0-9_-]{1,48}$/.test(doseId) || !TAP_INTENTS.includes(intent)) return null;
